import { Component, OnInit, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { WebsocketService } from '../../services/websocket.service';
import { AuthService } from '../../services/auth.service';
import { AuctionCard, BidUpdate } from '../../models/auction.model';

interface ToastMessage {
  type: 'success' | 'danger' | 'info' | 'warning';
  text: string;
  id: number;
}

@Component({
  selector: 'app-auction-detail',
  templateUrl: './auction-detail.component.html',
  styleUrls: ['./auction-detail.component.css']
})
export class AuctionDetailComponent implements OnInit, OnDestroy {
  auction: AuctionCard | null = null;
  auctionId!: number;
  currentBid = 0;
  highestBidder: string | null = null;
  auctionStatus = '';
  bidAmount: number | null = null;
  isConnected = false;
  isSubmitting = false;
  toasts: ToastMessage[] = [];
  private toastCounter = 0;
  bidHistory: { amount: number; bidder: string; time: Date }[] = [];

  private wsSub!: Subscription;
  private statusSub!: Subscription;

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private wsService: WebsocketService,
    private authService: AuthService
  ) {}

  ngOnInit(): void {
    this.auctionId = Number(this.route.snapshot.paramMap.get('id'));

    const state = history.state as { auction?: AuctionCard };
    if (state?.auction) {
      this.auction = state.auction;
      this.currentBid = this.auction.currentBid;
      this.highestBidder = this.auction.highestBidder;
      this.auctionStatus = this.auction.status;
    }

    this.connectWebSocket();
  }

  private connectWebSocket(): void {
    this.wsService.connect();

    this.statusSub = this.wsService.connectionStatus$.subscribe(status => {
      this.isConnected = status === 'CONNECTED';
      if (status === 'ERROR') {
        this.showToast('danger', 'WebSocket connection failed. Real-time updates unavailable.');
      }
    });

    this.wsSub = this.wsService.messages$.subscribe((msg: BidUpdate) => {
      if (msg.type === 'ERROR') {
        this.showToast('danger', msg.message || 'An error occurred.');
        this.isSubmitting = false;
        return;
      }

      if (msg.type === 'AUCTION_STARTED') {
        this.auctionStatus = 'LIVE';
        this.showToast('success', 'Auction has started! Place your bids now.');
        return;
      }

      if (msg.type === 'AUCTION_STOPPED') {
        this.auctionStatus = 'ENDED';
        this.showToast('info', 'Auction has ended.');
        return;
      }

      // Regular bid update
      if (msg.auctionId === this.auctionId || !msg.auctionId) {
        if (msg.amount !== undefined && msg.amount > this.currentBid) {
          const prevBidder = this.highestBidder;
          this.currentBid = msg.amount;
          this.highestBidder = msg.highestBidder || (msg.bidderId?.toString() ?? null);

          this.bidHistory.unshift({
            amount: msg.amount,
            bidder: this.highestBidder ?? 'Unknown',
            time: new Date()
          });

          const myId = this.authService.getUserId();
          if (myId && msg.bidderId === myId) {
            this.showToast('success', `Your bid of ${this.formatCurrency(msg.amount)} is now the highest!`);
          } else if (prevBidder) {
            this.showToast('info', `New highest bid: ${this.formatCurrency(msg.amount)}`);
          }
        }
        this.isSubmitting = false;
      }
    });
  }

  placeBid(): void {
    if (!this.bidAmount || this.bidAmount <= this.currentBid) {
      this.showToast('warning', `Bid must be greater than current bid of ${this.formatCurrency(this.currentBid)}.`);
      return;
    }

    const userId = this.authService.getUserId();
    if (!userId) {
      this.showToast('danger', 'User ID not found. Please set your User ID in Wallet settings.');
      return;
    }

    this.isSubmitting = true;
    this.wsService.sendBid({
      auctionId: this.auctionId,
      bidderId: userId,
      amount: this.bidAmount
    });

    this.bidAmount = null;
  }

  showToast(type: ToastMessage['type'], text: string): void {
    const id = ++this.toastCounter;
    this.toasts.push({ type, text, id });
    setTimeout(() => {
      this.toasts = this.toasts.filter(t => t.id !== id);
    }, 5000);
  }

  dismissToast(id: number): void {
    this.toasts = this.toasts.filter(t => t.id !== id);
  }

  formatCurrency(amount: number): string {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0
    }).format(amount);
  }

  goBack(): void {
    void this.router.navigate(['/home']);
  }

  ngOnDestroy(): void {
    this.wsService.disconnect();
    if (this.wsSub) this.wsSub.unsubscribe();
    if (this.statusSub) this.statusSub.unsubscribe();
  }
}
<!-- ========== Toast Container ========== -->
<div class="toast-container">
  <div
    *ngFor="let toast of toasts"
    class="toast show align-items-center border-0 mb-2 shadow-lg"
    [ngClass]="{
      'text-bg-success': toast.type === 'success',
      'text-bg-danger':  toast.type === 'danger',
      'text-bg-info':    toast.type === 'info',
      'text-bg-warning': toast.type === 'warning'
    }"
    role="alert"
    style="border-radius:12px;min-width:300px;">
    <div class="d-flex align-items-center">
      <div class="toast-body d-flex align-items-center gap-2">
        <i class="bi fs-5"
           [ngClass]="{
             'bi-check-circle-fill': toast.type === 'success',
             'bi-x-circle-fill':    toast.type === 'danger',
             'bi-info-circle-fill': toast.type === 'info',
             'bi-exclamation-triangle-fill': toast.type === 'warning'
           }"></i>
        <span>{{ toast.text }}</span>
      </div>
      <button type="button" class="btn-close btn-close-white me-2 m-auto"
              (click)="dismissToast(toast.id)"></button>
    </div>
  </div>
</div>

<!-- ========== Live Room Page ========== -->
<div class="live-room-bg">
  <div class="container py-4">

    <!-- Back Button -->
    <button class="btn btn-outline-light btn-sm mb-4 fw-semibold" (click)="goBack()">
      <i class="bi bi-arrow-left me-2"></i>Back to Auctions
    </button>

    <div class="row g-4">

      <!-- ===== LEFT PANEL — Product Info ===== -->
      <div class="col-lg-7">
        <div class="product-panel fade-in-up">

          <!-- No auction data fallback -->
          <div class="text-center py-5 text-muted" *ngIf="!auction">
            <i class="bi bi-search" style="font-size:3rem;opacity:0.4;"></i>
            <p class="mt-3">No auction data. Please go back and select an auction.</p>
          </div>

          <ng-container *ngIf="auction">
            <!-- Product Image -->
            <div class="product-img-wrapper mb-4">
              <img
                [src]="auction.product.imageUrl || 'https://placehold.co/700x400/1e3a5f/ffffff?text=No+Image'"
                class="product-main-img"
                [alt]="auction.product.productName"
                (error)="$any($event.target).src='https://placehold.co/700x400/1e3a5f/ffffff?text=No+Image'"
              />
              <!-- Status overlaid on image -->
              <div class="product-status-overlay">
                <span class="auction-status-pill"
                      [ngClass]="{
                        'status-pill-live':    auctionStatus === 'LIVE',
                        'status-pill-created': auctionStatus === 'CREATED',
                        'status-pill-ended':   auctionStatus === 'ENDED'
                      }">
                  <span class="live-dot-sm me-1" *ngIf="auctionStatus === 'LIVE'"></span>
                  <i class="bi bi-clock me-1" *ngIf="auctionStatus === 'CREATED'"></i>
                  <i class="bi bi-flag-fill me-1" *ngIf="auctionStatus === 'ENDED'"></i>
                  {{ auctionStatus }}
                </span>
              </div>
            </div>

            <!-- Product Details -->
            <div class="product-info-body">
              <!-- Category chip -->
              <span class="category-chip-detail mb-3 d-inline-flex">
                <i class="bi bi-tag me-1"></i>{{ auction.product.category?.categoryName || 'Uncategorized' }}
              </span>

              <h2 class="product-title mb-2">{{ auction.product.productName }}</h2>
              <p class="product-description mb-4">{{ auction.product.description }}</p>

              <div class="product-meta-row">
                <div class="product-meta-item">
                  <span class="meta-label">Starting Price</span>
                  <span class="meta-value">{{ formatCurrency(auction.product.startingPrice) }}</span>
                </div>
                <div class="product-meta-divider"></div>
                <div class="product-meta-item">
                  <span class="meta-label">Seller</span>
                  <span class="meta-value">
                    <i class="bi bi-person-check-fill me-1" style="color:#10b981;"></i>
                    {{ auction.product.seller?.name || 'Unknown' }}
                  </span>
                </div>
                <div class="product-meta-divider"></div>
                <div class="product-meta-item">
                  <span class="meta-label">Auction ID</span>
                  <span class="meta-value">#{{ auctionId }}</span>
                </div>
              </div>
            </div>
          </ng-container>
        </div>
      </div>

      <!-- ===== RIGHT PANEL — Bidding ===== -->
      <div class="col-lg-5">

        <!-- Connection Status Bar -->
        <div class="connection-bar mb-3 d-flex align-items-center gap-2"
             [ngClass]="isConnected ? 'connection-bar-live' : 'connection-bar-offline'">
          <span class="connection-dot"
                [ngClass]="isConnected ? 'dot-live' : 'dot-offline'"></span>
          <span class="connection-text">
            {{ isConnected ? 'Connected — Live Bidding Active' : 'Connecting to auction server...' }}
          </span>
          <span class="badge ms-auto" [ngClass]="isConnected ? 'bg-success' : 'bg-secondary'">
            {{ isConnected ? 'LIVE' : 'OFFLINE' }}
          </span>
        </div>

        <!-- Current Bid Card -->
        <div class="current-bid-card mb-3 fade-in-up">
          <p class="bid-label mb-1">Current Highest Bid</p>
          <div class="bid-amount" [class.bid-updated]="isConnected && auctionStatus === 'LIVE'">
            {{ formatCurrency(currentBid) }}
          </div>
          <div class="bid-leader mt-2" *ngIf="highestBidder">
            <i class="bi bi-trophy-fill me-1" style="color:#f59e0b;"></i>
            Leader: <strong>{{ highestBidder }}</strong>
          </div>
          <div class="bid-leader text-muted mt-2" *ngIf="!highestBidder">
            <i class="bi bi-person-plus me-1"></i>
            No bids yet — be the first!
          </div>
        </div>

        <!-- Place Bid Section (only if LIVE) -->
        <div class="place-bid-card mb-3 fade-in-up" *ngIf="auctionStatus === 'LIVE'">
          <h6 class="place-bid-title mb-3">
            <i class="bi bi-lightning-fill me-2" style="color:#f59e0b;"></i>Place Your Bid
          </h6>
          <div class="input-group mb-2">
            <span class="input-group-text bid-input-prefix fw-bold">&#x20B9;</span>
            <input
              type="number"
              class="form-control bid-input"
              placeholder="Enter bid amount"
              [(ngModel)]="bidAmount"
              [min]="currentBid + 1"
              [disabled]="isSubmitting"
            />
          </div>
          <p class="bid-min-hint mb-3">
            <i class="bi bi-info-circle me-1"></i>
            Minimum bid: <strong>{{ formatCurrency(currentBid + 1) }}</strong>
          </p>
          <button
            class="btn btn-accent w-100 fw-bold py-3 place-bid-btn"
            (click)="placeBid()"
            [disabled]="isSubmitting || !bidAmount">
            <span *ngIf="isSubmitting" class="spinner-border spinner-border-sm me-2"></span>
            <i *ngIf="!isSubmitting" class="bi bi-hammer me-2"></i>
            {{ isSubmitting ? 'Placing Bid...' : 'Place Bid' }}
          </button>
        </div>

        <!-- Upcoming Alert -->
        <div class="auction-status-alert alert-upcoming fade-in-up" *ngIf="auctionStatus === 'CREATED'">
          <div class="d-flex align-items-center gap-3">
            <div class="status-icon">
              <i class="bi bi-hourglass-split" style="font-size:1.8rem;animation:spin-slow 3s linear infinite;"></i>
            </div>
            <div>
              <p class="fw-bold mb-1">Waiting for Auction to Start</p>
              <p class="mb-0 small opacity-75">The admin will start this auction soon. Stay on this page to be ready!</p>
            </div>
          </div>
        </div>

        <!-- Ended Alert -->
        <div class="auction-status-alert alert-ended fade-in-up" *ngIf="auctionStatus === 'ENDED'">
          <div class="d-flex align-items-center gap-3">
            <div class="status-icon">
              <i class="bi bi-trophy-fill" style="font-size:1.8rem;color:#f59e0b;"></i>
            </div>
            <div>
              <p class="fw-bold mb-1">Auction Closed</p>
              <p class="mb-0 small" *ngIf="highestBidder">
                Winner: <strong>{{ highestBidder }}</strong>
              </p>
              <p class="mb-0 small opacity-75" *ngIf="!highestBidder">No bids were placed.</p>
            </div>
          </div>
        </div>

        <!-- Bid History -->
        <div class="bid-history-card fade-in-up" *ngIf="bidHistory.length > 0">
          <div class="bid-history-header">
            <i class="bi bi-clock-history me-2"></i>Recent Bids
            <span class="badge bg-dark ms-2 rounded-pill">{{ bidHistory.length }}</span>
          </div>
          <ul class="bid-history-list list-unstyled mb-0">
            <li class="bid-history-item"
                *ngFor="let bid of bidHistory.slice(0, 8); let i = index"
                [class.first-bid]="i === 0">
              <div class="d-flex align-items-center justify-content-between">
                <div class="bid-bidder">
                  <span class="bid-rank" *ngIf="i === 0">
                    <i class="bi bi-trophy-fill" style="color:#f59e0b;font-size:0.75rem;"></i>
                  </span>
                  <i class="bi bi-person-circle me-1 text-muted" *ngIf="i > 0"></i>
                  <span class="fw-semibold">{{ bid.bidder }}</span>
                </div>
                <div class="text-end">
                  <span class="bid-amount-sm fw-bold"
                        [ngClass]="i === 0 ? 'text-accent' : 'text-muted'">
                    {{ formatCurrency(bid.amount) }}
                  </span>
                  <br/>
                  <small class="text-muted" style="font-size:0.7rem;">{{ bid.time | date:'HH:mm:ss' }}</small>
                </div>
              </div>
            </li>
          </ul>
        </div>

      </div><!-- /right panel -->
    </div><!-- /row -->
  </div><!-- /container -->
</div><!-- /live-room-bg -->
